function transition(request,action){if(action==='confirm'&&request.state==='等待确认'){request.result=request.result||'sandbox-booking-'+request.id;request.writes=(request.writes||0)+1;request.state='成功'}if(action==='cancel'&&['等待确认','后台执行'].includes(request.state)){request.state='已取消';request.result=null}return request}
function localReplay(){const a={id:'fixture-1',state:'等待确认',writes:0};transition(a,'confirm');transition(a,'confirm');const b={id:'fixture-2',state:'等待确认',writes:0};transition(b,'cancel');transition(b,'confirm');const checks=[a.state==='成功',a.writes===1,Boolean(a.result),b.state==='已取消',!b.result,b.writes===0];return {passed:checks.filter(Boolean).length,total:checks.length}}
